INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Dokumentation für jede API zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Optional, aber empfohlen"}, {"text": "Ja", "correct": false, "because": "Nicht technisch notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer API-Dokumentation?', 3, '[{"text": "Nutzung verständlich machen", "correct": true, "because": "Erleichtert Integration"}, {"text": "Code ausführen", "correct": false, "because": "Kein direkter Zweck"}, {"text": "UI designen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer guten Dokumentation?', 5, '[{"text": "Endpunkte", "correct": true, "because": "Definieren Zugriffspunkte"}, {"text": "Parameter", "correct": true, "because": "Beschreiben Eingaben"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Endpunkte müssen beschrieben werden. b) Parameter sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Parameter können Pflicht sein"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Dokumentation?', 4, '[{"text": "API-Endpunkte", "correct": false, "because": "Kern der Nutzung"}, {"text": "Parameterbeschreibung", "correct": false, "because": "Wichtig für Eingaben"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dokumentation nur für Entwickler ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Nutzer hilfreich"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich, um einen Endpunkt zu erklären?', 3, '[{"text": "URL-Beschreibung", "correct": true, "because": "Zeigt Zugriffspunkt"}, {"text": "Farbanpassung", "correct": false, "because": "Nicht relevant"}, {"text": "Datenbankstruktur", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Dokumentation entscheidend?', 5, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Vollständigkeit", "correct": true, "because": "Deckt alle Fälle ab"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dokumentation spart Zeit. b) Sie ist nur für große Projekte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Auch kleine Projekte profitieren"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Dokumentation?', 4, '[{"text": "Endpunktliste", "correct": false, "because": "Zeigt API-Struktur"}, {"text": "Parameterdetails", "correct": false, "because": "Erklärt Eingaben"}, {"text": "3D-Animationen", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Dokumentation technisch sein?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch nutzerfreundlich sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Dokumentation?', 4, '[{"text": "Einfachere Integration", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Weniger Support", "correct": true, "because": "Klarheit reduziert Fragen"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Dokumentation oft veraltet ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Muss aktuell gehalten werden"}, {"text": "Nein", "correct": false, "because": "Abhängig von Pflege"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in der Dokumentation?', 3, '[{"text": "Verständlichkeit", "correct": true, "because": "Fördert Nutzung"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Serverkonfiguration", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Parameter müssen Typen haben. b) Endpunkte sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Endpunkte essenziell"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Dokumentation?', 5, '[{"text": "Missverständnisse", "correct": true, "because": "Fehlende Klarheit"}, {"text": "Fehlernutzung", "correct": true, "because": "Unklare Parameter"}, {"text": "Schnellere Integration", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Dokumentation unwichtig?', 3, '[{"text": "Beispiele", "correct": false, "because": "Fördern Verständnis"}, {"text": "Beschreibungen", "correct": false, "because": "Erklären Funktion"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Dokumentation automatisch erstellt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Tools wie Swagger möglich"}, {"text": "Nein", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dokumentation nur für Endpunkte ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Parameter und mehr"}, {"text": "Ja", "correct": false, "because": "Umfassender"}]'),
